INSERT INTO sources(title,publisher,url,publication_date,status,reviewed_at) VALUES ('Wal-Mart Stores Inc. 2013 EPA RCRA/FIFRA settlement','U.S. Environmental Protection Agency','https://www.epa.gov/enforcement/wal-mart-stores-inc-settlement','2013-05-28','approved',CURRENT_TIMESTAMP) ON CONFLICT(url) DO UPDATE SET title=excluded.title,publisher=excluded.publisher,publication_date=excluded.publication_date,status='approved',reviewed_at=CURRENT_TIMESTAMP;
INSERT INTO financial_records(company_id,source_id,category,record_type,description,recipient_name,amount,currency,period_start,period_end,evidence_level,review_status,reviewed_at) SELECT c.id,s.id,'Environmental enforcement','Civil penalty / EPA settlement','EPA describes a 2013 consent agreement resolving hazardous-waste and pesticide-law violations and requiring a $7.6 million federal civil penalty. Historical enforcement outcome, not evidence of current noncompliance.','United States government',7600000,'USD','2013-05-28','2013-05-28','EPA enforcement settlement','approved',CURRENT_TIMESTAMP FROM companies c JOIN sources s ON s.url='https://www.epa.gov/enforcement/wal-mart-stores-inc-settlement' WHERE c.slug='walmart' AND NOT EXISTS(SELECT 1 FROM financial_records f WHERE f.company_id=c.id AND f.source_id=s.id AND f.record_type='Civil penalty / EPA settlement');
INSERT INTO sources(title,publisher,url,publication_date,status,reviewed_at) VALUES ('Amazon Services LLC 2018 EPA FIFRA settlement','U.S. Environmental Protection Agency','https://www.epa.gov/enforcement/amazon-services-llc-fifra-settlement','2018-02-15','approved',CURRENT_TIMESTAMP) ON CONFLICT(url) DO UPDATE SET title=excluded.title,publisher=excluded.publisher,publication_date=excluded.publication_date,status='approved',reviewed_at=CURRENT_TIMESTAMP;
INSERT INTO financial_records(company_id,source_id,category,record_type,description,recipient_name,amount,currency,period_start,period_end,evidence_level,review_status,reviewed_at) SELECT c.id,s.id,'Environmental enforcement','Civil penalty / EPA settlement','EPA''s 2018 consent agreement with Amazon Services LLC concerning distribution of unregistered and misbranded pesticide products included a $1,215,700 administrative penalty. The named entity is Amazon Services LLC; this is a historical settlement.','United States government',1215700,'USD','2018-02-15','2018-02-15','EPA enforcement settlement','approved',CURRENT_TIMESTAMP FROM companies c JOIN sources s ON s.url='https://www.epa.gov/enforcement/amazon-services-llc-fifra-settlement' WHERE c.slug='amazon' AND NOT EXISTS(SELECT 1 FROM financial_records f WHERE f.company_id=c.id AND f.source_id=s.id AND f.record_type='Civil penalty / EPA settlement');
INSERT INTO sources(title,publisher,url,publication_date,status,reviewed_at) VALUES ('EPA settlement with Apple Inc. regarding Santa Clara hazardous waste','U.S. Environmental Protection Agency','https://www.epa.gov/newsreleases/epa-takes-action-against-apple-inadequate-hazardous-waste-management','2025-11-18','approved',CURRENT_TIMESTAMP) ON CONFLICT(url) DO UPDATE SET title=excluded.title,publisher=excluded.publisher,publication_date=excluded.publication_date,status='approved',reviewed_at=CURRENT_TIMESTAMP;
INSERT INTO financial_records(company_id,source_id,category,record_type,description,recipient_name,amount,currency,period_start,period_end,evidence_level,review_status,reviewed_at) SELECT c.id,s.id,'Environmental enforcement','Civil penalty / EPA settlement','EPA announced resolution of hazardous-waste management and air-emissions issues at Apple''s Santa Clara facility. EPA stated Apple addressed the issues and would pay a $261,283 penalty. This describes a resolved historical case.','United States government',261283,'USD','2025-11-18','2025-11-18','EPA enforcement settlement','approved',CURRENT_TIMESTAMP FROM companies c JOIN sources s ON s.url='https://www.epa.gov/newsreleases/epa-takes-action-against-apple-inadequate-hazardous-waste-management' WHERE c.slug='apple' AND NOT EXISTS(SELECT 1 FROM financial_records f WHERE f.company_id=c.id AND f.source_id=s.id AND f.record_type='Civil penalty / EPA settlement');
INSERT INTO relationships(company_id,source_id,target_name,relationship_type,description,review_status) SELECT c.id,s.id,'Greenleaf LLC','Historical waste management contractor','EPA states Greenleaf was under contract with Walmart to recycle pesticide products in 2006-2008. This establishes a historical contractual association, not a disclosed dollar transfer.','approved' FROM companies c JOIN sources s ON s.url='https://www.epa.gov/enforcement/wal-mart-stores-inc-settlement' WHERE c.slug='walmart' AND NOT EXISTS(SELECT 1 FROM relationships r WHERE r.company_id=c.id AND r.source_id=s.id AND r.target_name='Greenleaf LLC');
